module fsm_control (
        input clk,
        input rst,
        input trigger,
        input halt,
        output reg out);

    parameter WAIT = 0, RUN = 1, STOP = 2;
    reg [1:0] state, next_state;

    always @(posedge clk) begin
        if (rst) state <= WAIT;
        else state <= next_state;
    end

    always_comb begin
        case (state)
            WAIT: next_state = trigger ? RUN : WAIT;
            RUN: next_state = halt ? STOP : RUN;
            STOP: next_state = rst ? WAIT : STOP;
            default: next_state = 'x;
        endcase
    end

    assign out = (state == RUN) || (state == STOP);

endmodule

