module top_module(
	input reset, // active low
	input clock,
	input [7:0] read_data,
	input read_clock_enable,
	output reg ready, // ready to read new data
	output reg tx, // UART transmission
	output reg uart_clock
);parameter CLOCK_FREQ = 2400;
parameter BAUD_RATE = 1200;
parameter BIT_TIME = CLOCK_FREQ / BAUD_RATE;

reg [3:0] state;
reg [7:0] data;
reg start_bit;
reg [2:0] bit_count;
reg stop_bit;

assign uart_clock = clock;

always @(posedge clock) begin
	if (reset == 0) begin
		state <= 4'b0000;
		ready <= 0;
		tx <= 1;
		data <= 0;
		start_bit <= 0;
		bit_count <= 0;
		stop_bit <= 1;
	end else begin
		case (state)
			4'b0000: begin // wait for read clock enable
				if (read_clock_enable == 1) begin
					state <= 4'b0001;
				end
			end
			4'b0001: begin // wait for ready
				if (ready == 1) begin
					state <= 4'b0010;
					data <= read_data;
				end
			end
			4'b0010: begin // start bit
				start_bit <= 0;
				bit_count <= 0;
				stop_bit <= 1;
				state <= 4'b0011;
			end
			4'b0011: begin // data bits
				if (bit_count < 8) begin
					tx <= data[bit_count];
					bit_count <= bit_count + 1;
				end else begin
					state <= 4'b0100;
				end
			end
			4'b0100: begin // stop bit
				start_bit <= 1;
				bit_count <= 0;
				stop_bit <= 0;
				state <= 4'b0101;
			end
			4'b0101: begin // wait for stop bit
				if (bit_count >= BIT_TIME) begin
					state <= 4'b0000;
					ready <= 1;
				end else begin
					bit_count <= bit_count + 1;
				end
			end
			default: begin
				state <= 4'b0000;
			end
		endcase
	end
end

endmodule

