description:
Design a 4-bit signed Booth multiplier. This circuit takes two signed 4-bit inputs, a and b, and produces an 8-bit signed output by implementing Booth's algorithm for multiplication. It prepares the multiplicand by sign-extending it, adjusts the multiplier, and uses a combination of addition and bit manipulation to compute the product, which is then assigned to the output.
module top_module(
    input signed [3:0] a,
    input signed [3:0] b,
    output reg signed [7:0] out
);

code:
module top_module(
    input signed [3:0] a,
    input signed [3:0] b,
    output reg signed [7:0] out
);reg signed [3:0] m;
reg signed [4:0] p;
reg signed [4:0] n;
reg signed [8:0] result;

always @(*) begin
    m = {a[3], a};
    p = {b, 1'b0};
    n = {-b, 1'b0};
    result = m * p + n;
end

assign out = result[7:0];

endmodule

