module top_module(
    input           clk,
    input           reset,
    input           w,
    output          z
);parameter       SA  = 3'b000,
                    SB  = 3'b001,
                    SC  = 3'b010,
                    SD  = 3'b011,
                    SE  = 3'b100,
                    SF  = 3'b101;

    reg     [2:0]   state;
    reg     [2:0]   state_next;

    always @(posedge clk) begin
        if (reset)
            state <= SA;
        else
            state <= state_next;
    end

    always @(*) begin
        case (state)
        SA      : state_next = w ? SB : SA;
        SB      : state_next = w ? SC : SD;
        SC      : state_next = w ? SE : SD;
        SD      : state_next = w ? SF : SA;
        SE      : state_next = w ? SE : SD;
        SF      : state_next = w ? SC : SD;
        default : state_next = SA;
        endcase
    end

    assign z = (state == SE) | (state == SF);

endmodule

