module top_module (
        input clk,
        input areset,
        input coin_inserted,
        input turnstile_passed,
        output reg unlocked);parameter Locked=1'b0, Unlocked=1'b1;
	reg state;
	always @(posedge clk, posedge areset) begin
		if (areset)
			state <= Locked;
		else begin
			case (state)
				Locked: state <= coin_inserted ? Unlocked : Locked;
				Unlocked: state <= turnstile_passed ? Locked : Unlocked;
			endcase
		end
	end

	assign unlocked = (state == Unlocked);

endmodule

