    );

    // Clock generation (10ns period)
    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

        task reset_dut;

        begin
            reset = 1;
            signal = 0;
            mode_select = 0;
            repeat(2) @(posedge clk);
            #1 reset = 0;
            repeat(1) @(posedge clk);
        end
        endtask
    task testcase001;

        begin
            test_num = 1;
            $display("\nTestcase %03d: 10-cycle Pulse Duration", test_num);
            reset_dut();
            mode_select = 1;
            @(posedge clk);
            #1 signal = 1;
            repeat(10) @(posedge clk);
            #1 signal = 0;
            @(posedge clk);
