Design a Phase-Locked Loop (PLL) circuit that generates a synthesized clock output with a configurable frequency. The PLL takes a reference clock input and utilizes feedback mechanisms to synchronize with the desired frequency, producing an output clock signal that can be used for a variety of applications. The design incorporates a phase detector to compare the feedback and reference signals, a loop filter to stabilize the phase difference, and programmable dividers to control the feedback and reference paths. When the control signal is active, the circuit adjusts the output of a voltage-controlled oscillator (VCO) based on the filtered phase difference, ultimately generating a stable synthesized clock output at twice the frequency of the reference clock, given appropriate settings for the programmable dividers.
module top_module(
  input ref_clk,
  input ctrl,
  output reg synth_clk // Changed to reg to allow assignment in always block
);

code:
module top_module(
  input ref_clk,
  input ctrl,
  output reg synth_clk // Changed to reg to allow assignment in always block
);parameter f_ref = 50_000_000; // frequency of the reference clock signal
parameter f_synth = 100_000_000; // desired frequency of the synthesized clock signal
parameter f_vco = 1_000_000_000; // frequency of the voltage-controlled oscillator
parameter N = 10; // programmable divider value for the feedback path
parameter M = 5; // programmable divider value for the reference path

reg [31:0] phase_accumulator = 0;
reg [31:0] feedback_divider = 0;
reg [31:0] reference_divider = 0;

reg [31:0] filtered_difference = 0; // Changed to reg to allow assignment
reg [31:0] vco_output = 0; // Changed to reg to allow assignment

wire [31:0] feedback_signal;
wire [31:0] reference_signal;

wire [31:0] phase_difference;

assign feedback_signal = vco_output >> N;
assign reference_signal = ref_clk >> M;

assign phase_difference = feedback_signal - reference_signal;

// Phase detector
always @(posedge ref_clk or posedge synth_clk) begin
  if (synth_clk) begin
    phase_accumulator <= phase_accumulator + phase_difference;
  end
end

// Loop filter
always @(posedge ref_clk) begin
  if (ctrl) begin
    filtered_difference <= (filtered_difference + phase_accumulator) >> 1;
  end
end

// VCO frequency divider
always @(posedge ref_clk) begin
  feedback_divider <= feedback_divider + 1;
  if (feedback_divider == N) begin
    feedback_divider <= 0;
  end
end

// Reference frequency divider
always @(posedge ref_clk) begin
  reference_divider <= reference_divider + 1;
  if (reference_divider == M) begin
    reference_divider <= 0;
  end
end

// VCO
always @(posedge ref_clk) begin
  if (ctrl) begin
    vco_output <= vco_output + filtered_difference;
  end
end

// Synthesized clock output
always @(posedge ref_clk) begin
  synth_clk <= vco_output >> N; // Assign to synth_clk in an always block
end

endmodule

