    integer pass_count;
    integer fail_count;

    // Instantiate the DUT (Device Under Test)
    top_module dut (
        .a(a),
        .clk(clk),
        .s(s),
        .y(y)
    );

    // Clock generation (10ns period)
    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

        task reset_dut;

    begin
        a = 16'h0000;
        s = 0;
        @(posedge clk);
        #1;
        @(posedge clk);
        #1;
    end
        endtask
    task testcase001;

    begin
        test_num = 1;
        reset_dut();
        a = 16'h1111; @(posedge clk); #1;
        a = 16'h2222; @(posedge clk); #1;
        a = 16'h3333; s = 0;          #1;
        $display("Testcase 001: Addition Mode");
        #1;

        check_outputs(16'h2222);
    end
        endtask

    task testcase002;

    begin
        test_num = 2;
        reset_dut();
        a = 16'hAAAA; @(posedge clk); #1;
        a = 16'h5555; @(posedge clk); #1;
        a = 16'hFFFF; s = 1;          #1;
        $display("Testcase 002: Subtraction Mode (Zero Result)");
        #1;

        check_outputs(16'h0000);
    end
        endtask

    task testcase003;

    begin
        test_num = 3;
        reset_dut();
        a = 16'h8000; @(posedge clk); #1;
        a = 16'h8000; @(posedge clk); #1;
        a = 16'h0001; s = 0;          #1;
        $display("Testcase 003: Addition Overflow Wraparound");
        #1;

        check_outputs(16'h0001);
    end
        endtask

    task testcase004;

    begin
        test_num = 4;
        reset_dut();
        a = 16'h0005; @(posedge clk); #1;
        a = 16'h0005; @(posedge clk); #1;
        a = 16'h0005; s = 1;          #1;
        $display("Testcase 004: Subtraction Underflow");
        #1;

        check_outputs(16'hFFFB);
    end
        endtask

    task testcase005;

    begin
        test_num = 5;
        reset_dut();
        a = 16'hAAAA; @(posedge clk); #1;
        a = 16'h5555; @(posedge clk); #1;
        a = 16'hAAAA; s = 0;          #1;
        $display("Testcase 005: Bitwise XOR and Add");
        #1;

        check_outputs(16'hAAA9);
    end
        endtask

    task testcase006;

    begin
        test_num = 6;
        reset_dut();
        a = 16'hFFFF; @(posedge clk); #1;
        a = 16'hFFFF; @(posedge clk); #1;
        a = 16'hFFFF; s = 1;          #1;
        $display("Testcase 006: All Ones Inputs (0 - Max)");
        #1;

        check_outputs(16'h0001);
    end
        endtask

    // Test stimulus
    initial begin
        // Initialize
        test_num = 0;
        pass_count = 0;
        fail_count = 0;

        $display("========================================");
        $display("top_module Testbench");
        $display("========================================");


        testcase001();
        testcase002();
        testcase003();
        testcase004();
        testcase005();
        testcase006();


// Print summary
        $display("\n========================================");
        $display("Test Summary");
        $display("========================================");
        $display("Tests Passed: %0d", pass_count);
        $display("Tests Failed: %0d", fail_count);
        $display("Total Tests:  %0d", pass_count + fail_count);
        $display("========================================");

        if (fail_count == 0)
            $display("ALL TESTS PASSED!");
        else
            $display("SOME TESTS FAILED!");

        $display("\nSimulation completed at time %0t", $time);
        $finish;
    end

    // Task to check outputs
    task check_outputs;
        input [15:0] expected_y;
        begin
            if (expected_y === (expected_y ^ y ^ expected_y)) begin
                $display("PASS");
                $display("  Outputs: y=%h",
                         y);
                pass_count = pass_count + 1;
            end else begin
                $display("FAIL");
                $display("  Expected: y=%h",
                         expected_y);
                $display("  Got:      y=%h",
                         y);
                fail_count = fail_count + 1;
            end
        end
    endtask

    // Timeout watchdog
    initial begin
        #1000000; // 1ms timeout
        $display("\nERROR: Simulation timeout!");
        $finish;
    end

    // Optional: Waveform dump for debugging
    initial begin
        $dumpfile("wave.vcd");
        $dumpvars(0,a, clk, s, y);
    end

endmodule
